PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, login_name TEXT NOT NULL COLLATE NOCASE UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('administrator','preparer','reader')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL, last_seen INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS books(id TEXT PRIMARY KEY, title TEXT NOT NULL, creator_user_id TEXT NOT NULL REFERENCES users(id), published_edition_id TEXT, created_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS book_access(book_id TEXT NOT NULL REFERENCES books(id), user_id TEXT NOT NULL REFERENCES users(id), level TEXT NOT NULL CHECK(level IN ('read','prepare')), granted_by TEXT NOT NULL REFERENCES users(id), granted_at TEXT NOT NULL, PRIMARY KEY(book_id,user_id));
CREATE TABLE IF NOT EXISTS book_editions(id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id), edition_number INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','abandoned','published','superseded')), revision INTEGER NOT NULL DEFAULT 0, published_at TEXT, UNIQUE(book_id,edition_number));
CREATE UNIQUE INDEX IF NOT EXISTS one_draft ON book_editions(book_id) WHERE status IN ('draft','abandoned');
CREATE TABLE IF NOT EXISTS edition_settings(edition_id TEXT NOT NULL REFERENCES book_editions(id), id TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(edition_id,id));
CREATE TABLE IF NOT EXISTS source_assets(book_id TEXT NOT NULL REFERENCES books(id), id TEXT NOT NULL, storage_key TEXT NOT NULL, sha256 TEXT NOT NULL, mime TEXT NOT NULL, byte_size INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(book_id,id));
CREATE TABLE IF NOT EXISTS edition_sources(edition_id TEXT NOT NULL REFERENCES book_editions(id), source_id TEXT NOT NULL, PRIMARY KEY(edition_id,source_id));
CREATE TABLE IF NOT EXISTS pages(edition_id TEXT NOT NULL REFERENCES book_editions(id), id TEXT NOT NULL, source_id TEXT NOT NULL, position REAL NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(edition_id,id));
CREATE TABLE IF NOT EXISTS page_text_versions(edition_id TEXT NOT NULL REFERENCES book_editions(id), page_id TEXT NOT NULL, revision INTEGER NOT NULL, text TEXT NOT NULL, source_kind TEXT NOT NULL, words_json TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, PRIMARY KEY(edition_id,page_id,revision));
CREATE TABLE IF NOT EXISTS page_reviews(edition_id TEXT NOT NULL REFERENCES book_editions(id), page_id TEXT NOT NULL, text_version INTEGER NOT NULL, crop_version INTEGER NOT NULL, reviewer_id TEXT NOT NULL REFERENCES users(id), payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS annotations(user_id TEXT NOT NULL REFERENCES users(id), book_id TEXT NOT NULL REFERENCES books(id), edition_id TEXT NOT NULL REFERENCES book_editions(id), id TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,edition_id,id));
CREATE TABLE IF NOT EXISTS bookmarks(user_id TEXT NOT NULL REFERENCES users(id), book_id TEXT NOT NULL REFERENCES books(id), edition_id TEXT NOT NULL REFERENCES book_editions(id), id TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(user_id,edition_id,id));
CREATE TABLE IF NOT EXISTS reading_progress(user_id TEXT NOT NULL REFERENCES users(id), edition_id TEXT NOT NULL REFERENCES book_editions(id), page_id TEXT NOT NULL, is_read INTEGER NOT NULL, PRIMARY KEY(user_id,edition_id,page_id));
CREATE TABLE IF NOT EXISTS reader_preferences(user_id TEXT NOT NULL REFERENCES users(id), edition_id TEXT NOT NULL REFERENCES book_editions(id), payload TEXT NOT NULL CHECK(json_valid(payload)), revision INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,edition_id));
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, target_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_batches(id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id), user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, created_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE IF NOT EXISTS processing_jobs(id TEXT PRIMARY KEY, book_id TEXT REFERENCES books(id), user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, finished_at TEXT);
CREATE VIRTUAL TABLE IF NOT EXISTS page_search USING fts5(edition_id UNINDEXED, page_id UNINDEXED, text);
INSERT OR IGNORE INTO schema_migrations VALUES(1,'Initial local accounts and book editions',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
